/**
 * Main Application Class for SAP CAP + SAP IAS Backend
 *
 * Bachelor Thesis: Comparing SAP CAP + SAP IAS vs. AWS Cognito + Spring Boot
 *
 * Key Hypotheses:
 * - H1: SAP CAP requires significantly less security code (70% reduction expected)
 * - H2: SAP CAP provides better maintainability through central security definition
 * - H3a: Setup time and Time-to-First-Token comparison
 * - H4: SAP CAP has less coupling to security libraries (70% reduction expected)
 * - H5: SAP CAP provides automatic token validation (NO manual JWKS code)
 * - H6: SAP CAP simplifies registration flow (configuration vs. code)
 * - H7: SAP CAP provides native password reset with rate-limiting
 *
 * CRITICAL DIFFERENCE:
 * - AWS Cognito: IMPERATIVE security (code in every method)
 * - SAP CAP: DECLARATIVE security (CDS annotations in model)
 */
@SpringBootApplication
public class Application {

	private static final Logger logger = LoggerFactory.getLogger(Application.class);

	public static void main(String[] args) {
		logger.info("==========================================================");
		logger.info("SAP CAP + SAP IAS BACKEND - BACHELOR THESIS CASE STUDY");
		logger.info("==========================================================");
		logger.info("SAP_CAP_SETUP_START: {}", LocalDateTime.now());
		logger.info("Framework: SAP Cloud Application Programming Model");
		logger.info("Identity Provider: SAP Identity Authentication Service (IAS)");
		logger.info("Security Model: DECLARATIVE (CDS Annotations)");
		logger.info("");
		logger.info("Measuring Hypotheses:");
		logger.info("  H1: Security Code Lines (Expected: 70% less than AWS)");
		logger.info("  H2: Maintainability (Central vs. Distributed)");
		logger.info("  H3a: Setup Time & Time-to-First-Token");
		logger.info("  H4: Security Coupling (Expected: 70% less than AWS)");
		logger.info("  H5: Token Validation (AUTOMATIC vs. Manual)");
		logger.info("  H6: Registration Flow (Configuration vs. Code)");
		logger.info("  H7: Password Reset Security (Native Rate-Limiting)");
		logger.info("==========================================================");

		SpringApplication.run(Application.class, args);

		logger.info("==========================================================");
		logger.info("SAP CAP + SAP IAS BACKEND STARTED SUCCESSFULLY");
		logger.info("Server running on port: 8080");
		logger.info("OData V4 Endpoint: http://localhost:8080/odata/v4/OrderService");
		logger.info("Metrics Endpoint: http://localhost:8080/api/metrics/report");
		logger.info("");
		logger.info("Key Differences vs. AWS Cognito:");
		logger.info("  - NO manual JWT validation code (AUTOMATIC)");
		logger.info("  - NO @PreAuthorize annotations (CDS @restrict)");
		logger.info("  - NO distributed security checks (CENTRAL in CDS)");
		logger.info("  - NO service-binding manual configuration (AUTOMATIC)");
		logger.info("  - NO manual rate-limiting code (SAP IAS native)");
		logger.info("==========================================================");
	}
}

package customer.ba_backend_cap_ias.handlers;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import com.sap.cds.services.cds.CdsCreateEventContext;
import com.sap.cds.services.cds.CdsReadEventContext;
import com.sap.cds.services.handler.EventHandler;
import com.sap.cds.services.handler.annotations.Before;
import java.time.Instant;

@Component
public class OrderServiceHandler implements EventHandler {

    private static final Logger logger = LoggerFactory.getLogger(OrderServiceHandler.class);

    @Before(entity = "OrderService.Orders")
    public void beforeCreateOrder(CdsCreateEventContext context) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_CREATE: user={}, timestamp={}", username, Instant.now());
        logger.info("AUTHORIZATION_METHOD: AUTOMATIC_VIA_CDS_RESTRICT_ANNOTATION");

        context.getCqn().entries().forEach(entry -> {
            if (!entry.containsKey("createdBy")) {
                entry.put("createdBy", username);
            }
        });
    }

    @Before(event = "READ", entity = "OrderService.Orders")
    public void beforeReadOrders(CdsReadEventContext context) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_READ: user={}, roles={}",
                username,
                auth != null ? auth.getAuthorities() : "none");
        logger.info("AUTHORIZATION_ENFORCEMENT: AUTOMATIC_BY_FRAMEWORK");
    }

    public void onCompleteOrder() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_COMPLETE: user={}", username);
        logger.info("NO_MANUAL_AUTHORIZATION_CODE: Framework handled it automatically");
    }

    public void onCancelOrder() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_CANCEL: user={}", username);
    }
}

package customer.ba_backend_cap_ias.handlers;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import com.sap.cds.services.cds.CdsCreateEventContext;
import com.sap.cds.services.cds.CdsReadEventContext;
import com.sap.cds.services.handler.EventHandler;
import com.sap.cds.services.handler.annotations.Before;
import java.time.Instant;

@Component
public class OrderServiceHandler implements EventHandler {

    private static final Logger logger = LoggerFactory.getLogger(OrderServiceHandler.class);

    @Before(entity = "OrderService.Orders")
    public void beforeCreateOrder(CdsCreateEventContext context) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_CREATE: user={}, timestamp={}", username, Instant.now());
        logger.info("AUTHORIZATION_METHOD: AUTOMATIC_VIA_CDS_RESTRICT_ANNOTATION");

        context.getCqn().entries().forEach(entry -> {
            if (!entry.containsKey("createdBy")) {
                entry.put("createdBy", username);
            }
        });
    }

    @Before(event = "READ", entity = "OrderService.Orders")
    public void beforeReadOrders(CdsReadEventContext context) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_READ: user={}, roles={}",
                username,
                auth != null ? auth.getAuthorities() : "none");
        logger.info("AUTHORIZATION_ENFORCEMENT: AUTOMATIC_BY_FRAMEWORK");
    }

    public void onCompleteOrder() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_COMPLETE: user={}", username);
        logger.info("NO_MANUAL_AUTHORIZATION_CODE: Framework handled it automatically");
    }

    public void onCancelOrder() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth != null ? auth.getName() : "anonymous";

        logger.info("ORDER_CANCEL: user={}", username);
    }
}

package fh.babackendspringcognito;

import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.EnableConfigurationProperties;

import java.time.LocalDateTime;

/**
 * Main Application Class for AWS Cognito Backend.
 * 
 * This application demonstrates AWS Cognito integration for a Bachelor Thesis
 * comparing AWS Cognito vs. SAP IAS.
 * 
 * Measured Hypotheses:
 * - H1: Security implementation complexity (Lines of Code) - IMPERATIVE approach
 * - H2: Role-based authorization maintainability (distributed @PreAuthorize)
 * - H3a: Time-to-First-Token (Setup + Configuration)
 * - H4: Security coupling (dependency analysis across files)
 * - H5: Token validation complexity (manual JWKS configuration)
 * - H6: Registration flow implementation effort (manual AWS SDK integration)
 * - H7: Password reset security (AWS Cognito features + manual implementation)
 * 
 * CRITICAL DIFFERENCE vs. SAP CAP:
 * - AWS Cognito: IMPERATIVE security (@PreAuthorize on every method)
 * - SAP CAP: DECLARATIVE security (CDS @restrict annotations)
 */
@Slf4j
@SpringBootApplication
@EnableConfigurationProperties
public class BaBackendSpringCognitoApplication {

    public static void main(String[] args) {
        log.info("==========================================================");
        log.info("AWS COGNITO BACKEND - BACHELOR THESIS CASE STUDY");
        log.info("==========================================================");
        log.info("AWS_COGNITO_SETUP_START: {}", LocalDateTime.now());
        log.info("Framework: Spring Boot + Spring Security");
        log.info("Identity Provider: AWS Cognito User Pool");
        log.info("Security Model: IMPERATIVE (@PreAuthorize Annotations)");
        log.info("");
        log.info("Measuring Hypotheses:");
        log.info("  H1: Security Code Lines (Expected: 30-50 lines distributed)");
        log.info("  H2: Maintainability (Distributed @PreAuthorize)");
        log.info("  H3a: Setup Time & Time-to-First-Token");
        log.info("  H4: Security Coupling (Expected: 5-8 files with AWS imports)");
        log.info("  H5: Token Validation (Manual JWKS Configuration)");
        log.info("  H6: Registration Flow (Manual AWS SDK Implementation)");
        log.info("  H7: Password Reset Security (AWS Cognito Features)");
        log.info("==========================================================");

        SpringApplication.run(BaBackendSpringCognitoApplication.class, args);

        log.info("==========================================================");
        log.info("AWS COGNITO BACKEND STARTED SUCCESSFULLY");
        log.info("Server running on port: 8081");
        log.info("H2 Console: http://localhost:8081/h2-console");
        log.info("Metrics Endpoint: http://localhost:8081/api/metrics/report");
        log.info("");
        log.info("Key Differences vs. SAP CAP:");
        log.info("  - IMPERATIVE security (@PreAuthorize on every method)");
        log.info("  - MANUAL JWT validation configuration (JWKS URI)");
        log.info("  - DISTRIBUTED security checks (across 5-8 files)");
        log.info("  - MANUAL AWS SDK integration (SignUp, ForgotPassword, etc.)");
        log.info("  - PARTIAL rate-limiting (needs manual implementation)");
        log.info("==========================================================");
    }
}

